package com.hrcoresystem.hrcore_api.modules.tenant.incidents.infrastructure.persistence;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import lombok.Getter; import lombok.Setter; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import com.fasterxml.jackson.databind.JsonNode;
@Entity @Table(name="incident_history") @Getter @Setter public class IncidentHistoryEntity { @Id private UUID id; @Column(name="incident_id",nullable=false) private UUID incidentId; @Column(nullable=false) private String action; @Column(name="previous_status") private String previousStatus; @Column(name="new_status") private String newStatus; @JdbcTypeCode(SqlTypes.JSON) @Column(columnDefinition="jsonb") private JsonNode details; @Column(columnDefinition="TEXT") private String comment; @Column(name="performed_by") private UUID performedBy; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @PrePersist void created(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();} }
